-- Generated by local CLI; advanced after the two foundation migrations.
-- Local candidate only. No terms/channel/tax configuration or provider execution.
begin;
create table private.master_checkout_terms (
 plan_version_id uuid primary key references public.billing_plan_versions(id) on delete restrict,
 terms_version text not null check(length(btrim(terms_version)) between 1 and 128),
 terms_text text not null check(length(btrim(terms_text)) between 1 and 100000),
 features_version text not null check(length(btrim(features_version)) between 1 and 128),
 features jsonb not null check(jsonb_typeof(features)='array'),
 disclosed_charges jsonb not null check(jsonb_typeof(disclosed_charges)='array' and disclosed_charges::text not ilike '%UNCONFIGURED%'),
 approval_reference text not null check(length(btrim(approval_reference))>0),
 approved_at timestamptz not null default clock_timestamp()
);
create table private.master_checkout_quotes (
 checkout_id uuid primary key default gen_random_uuid(),
 order_id uuid not null unique references public.billing_orders(id) on delete restrict,
 company_id uuid not null references public.companies(id) on delete restrict,
 quoted_at timestamptz not null,
 quote_expires_at timestamptz not null,
 snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),
 check(quote_expires_at=quoted_at+interval '15 minutes')
);
create table private.master_checkout_consents (
 checkout_id uuid primary key references private.master_checkout_quotes(checkout_id) on delete restrict,
 actor_id uuid not null references auth.users(id) on delete restrict,
 actor_session_id uuid not null references auth.sessions(id) on delete restrict,
 terms_version text not null,
 accepted_at timestamptz not null default clock_timestamp()
);
alter table private.master_checkout_terms enable row level security;
alter table private.master_checkout_quotes enable row level security;
alter table private.master_checkout_consents enable row level security;
revoke all on private.master_checkout_terms,private.master_checkout_quotes,private.master_checkout_consents from public,anon,authenticated,service_role;
create function private.master_checkout_immutable() returns trigger language plpgsql set search_path='' as $$begin
 raise exception 'CHECKOUT_IMMUTABLE' using errcode='22023';
end;$$;
create trigger master_checkout_terms_immutable before update or delete on private.master_checkout_terms for each row execute function private.master_checkout_immutable();
create trigger master_checkout_terms_no_truncate before truncate on private.master_checkout_terms for each statement execute function private.master_checkout_immutable();
create trigger master_checkout_quote_immutable before update or delete on private.master_checkout_quotes for each row execute function private.master_checkout_immutable();
create trigger master_checkout_quote_no_truncate before truncate on private.master_checkout_quotes for each statement execute function private.master_checkout_immutable();
create trigger master_checkout_consent_immutable before update or delete on private.master_checkout_consents for each row execute function private.master_checkout_immutable();
create trigger master_checkout_consent_no_truncate before truncate on private.master_checkout_consents for each statement execute function private.master_checkout_immutable();

create function private.master_checkout_pin_quote() returns trigger language plpgsql security definer set search_path='' as $$
declare t private.master_checkout_terms%rowtype;pv public.billing_plan_versions%rowtype;channels jsonb;
begin
 if new.provider_environment<>'live' then return new;end if;
 select * into t from private.master_checkout_terms where plan_version_id=new.plan_version_id for share;
 if not found or t.approved_at>clock_timestamp() then raise exception 'CHECKOUT_TERMS_UNCONFIGURED';end if;
 select * into pv from public.billing_plan_versions where id=new.plan_version_id for share;
 channels:=jsonb_build_object('status','UNCONFIGURED');
 if to_regclass('private.plan_channel_entitlements') is not null then
  execute 'select jsonb_build_object(''status'',''approved'',''channelCount'',channel_count,''approvalReference'',approval_reference) from private.plan_channel_entitlements where plan_version_id=$1 and approved_at<=clock_timestamp()' into channels using new.plan_version_id;
  channels:=coalesce(channels,jsonb_build_object('status','UNCONFIGURED'));
 end if;
 insert into private.master_checkout_quotes(order_id,company_id,quoted_at,quote_expires_at,snapshot)
 values(new.id,new.company_id,new.locked_at,new.expires_at,jsonb_build_object(
  'planVersionId',new.plan_version_id,'planId',pv.plan_id,'amountBaisa',new.amount_baisa,'currency',new.currency,
  'periodDays',new.period_days,'periodUnit',new.period_unit,'periodCount',new.period_count,'replyLimits',pv.limits,
  'featuresVersion',t.features_version,'features',t.features,'disclosedCharges',t.disclosed_charges,
  'channelEntitlements',channels,'termsVersion',t.terms_version,'termsText',t.terms_text,'approvalReference',t.approval_reference));
 return new;
end;$$;
create function private.master_checkout_order_clock() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='INSERT' and new.provider_environment='live' then new.expires_at:=new.locked_at+interval '15 minutes';
 elsif tg_op='UPDATE' and exists(select 1 from private.master_checkout_quotes where order_id=old.id)
  and new.expires_at is distinct from old.expires_at then raise exception 'CHECKOUT_IMMUTABLE' using errcode='22023';end if;
 return new;
end;$$;
create trigger master_checkout_order_immutable before insert or update on public.billing_orders for each row execute function private.master_checkout_order_clock();
create trigger master_checkout_order_snapshot after insert on public.billing_orders for each row execute function private.master_checkout_pin_quote();

create function public.master_read_checkout_terms(p_company_id uuid,p_plan_version_id uuid,p_actor_id uuid,p_actor_session_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$declare t private.master_checkout_terms%rowtype;begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege;end if;
 if not private.billing_live_owner(p_company_id,p_actor_id,p_actor_session_id) then return jsonb_build_object('ok',false,'code','FORBIDDEN');end if;
 select * into t from private.master_checkout_terms where plan_version_id=p_plan_version_id and approved_at<=clock_timestamp();
 if not found then return jsonb_build_object('ok',false,'code','CHECKOUT_TERMS_UNCONFIGURED');end if;
 return jsonb_build_object('ok',true,'termsVersion',t.terms_version,'termsText',t.terms_text,'featuresVersion',t.features_version,'features',t.features,'disclosedCharges',t.disclosed_charges);
end;$$;
create function public.master_accept_checkout_consent(p_company_id uuid,p_order_id uuid,p_actor_id uuid,p_actor_session_id uuid,p_terms_version text,p_accepted boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare q private.master_checkout_quotes%rowtype;prior private.master_checkout_consents%rowtype;begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege;end if;
 perform 1 from public.companies where id=p_company_id for update;
 if not private.billing_live_owner(p_company_id,p_actor_id,p_actor_session_id) then return jsonb_build_object('ok',false,'code','FORBIDDEN');end if;
 select * into q from private.master_checkout_quotes where order_id=p_order_id and company_id=p_company_id;
 if q.checkout_id is null then return jsonb_build_object('ok',false,'code','CHECKOUT_QUOTE_REQUIRED');end if;
 if p_accepted is distinct from true then return jsonb_build_object('ok',false,'code','CHECKOUT_CONSENT_REQUIRED');end if;
 if p_terms_version is distinct from q.snapshot->>'termsVersion' then return jsonb_build_object('ok',false,'code','CHECKOUT_TERMS_CHANGED');end if;
 select * into prior from private.master_checkout_consents where checkout_id=q.checkout_id;
 if found then
  if prior.actor_id<>p_actor_id or prior.terms_version<>p_terms_version then return jsonb_build_object('ok',false,'code','CHECKOUT_CONSENT_CONFLICT');end if;
  return jsonb_build_object('ok',true,'checkoutId',q.checkout_id,'expiresAt',q.quote_expires_at);
 end if;
 if q.quote_expires_at<=clock_timestamp() then return jsonb_build_object('ok',false,'code','CHECKOUT_QUOTE_EXPIRED');end if;
 insert into private.master_checkout_consents(checkout_id,actor_id,actor_session_id,terms_version) values(q.checkout_id,p_actor_id,p_actor_session_id,p_terms_version);
 return jsonb_build_object('ok',true,'checkoutId',q.checkout_id,'expiresAt',q.quote_expires_at);
end;$$;

-- Patch native SQL bodies with checked anchors, retaining provider proof,
-- RBAC/session validation, company lock ordering and settlement implementation.
-- The reviewed live upgrade package is optional: absent functions stay absent.
do $$declare f regprocedure;d text;anchor text;guard text;begin
 f:=to_regprocedure('public.billing_create_live_checkout_order(uuid,uuid,uuid,uuid,text,bigint,bigint,text,integer)');
 if f is not null then
  d:=replace(pg_get_functiondef(f),chr(13),'');anchor:=' select revision into r from public.billing_catalog_revision';
  guard:=' if not exists(select 1 from private.master_checkout_terms where plan_version_id=p_plan_version_id and approved_at<=clock_timestamp()) then return jsonb_build_object(''ok'',false,''code'',''CHECKOUT_TERMS_UNCONFIGURED'');end if;';
  if (length(d)-length(replace(d,anchor,'')))/length(anchor)<>1 then raise exception 'CHECKOUT_CREATE_BODY_REQUIRES_REVIEW';end if;
  execute replace(d,anchor,guard||E'\n'||anchor);
 end if;
 f:=to_regprocedure('public.billing_claim_live_checkout(uuid,uuid,uuid,uuid,uuid)');
 if f is not null then
  d:=replace(pg_get_functiondef(f),chr(13),'');anchor:=' if o.id is null or a.id is null';
  guard:=$guard$
 if o.id is not null and a.id is not null then
  if not exists(select 1 from private.master_checkout_quotes q join private.master_checkout_consents c using(checkout_id) where q.order_id=o.id and q.company_id=p_company_id and c.actor_id=p_actor_id and c.terms_version=q.snapshot->>'termsVersion') then return jsonb_build_object('kind','rejected','code','CHECKOUT_CONSENT_REQUIRED');end if;
  if o.expires_at<=clock_timestamp() then
   if a.status in ('unresolved','provider_submitted') or exists(select 1 from private.billing_live_checkouts where payment_attempt_id=a.id) then return jsonb_build_object('kind','pending','code','PAYMENT_RECONCILIATION_REQUIRED');end if;
   return jsonb_build_object('kind','rejected','code','CHECKOUT_QUOTE_EXPIRED');
  end if;
 end if;
 $guard$;
  if (length(d)-length(replace(d,anchor,'')))/length(anchor)<>1 then raise exception 'CHECKOUT_CLAIM_BODY_REQUIRES_REVIEW';end if;
  execute replace(d,anchor,guard||E'\n'||anchor);
 end if;
 f:=to_regprocedure('public.billing_complete_live_checkout(uuid,uuid,uuid,uuid,uuid,text,text,text)');
 if f is not null then
  d:=replace(pg_get_functiondef(f),chr(13),'');anchor:=' or o.expires_at<=clock_timestamp()';
  if (length(d)-length(replace(d,anchor,'')))/length(anchor)<>1 then raise exception 'CHECKOUT_COMPLETE_BODY_REQUIRES_REVIEW';end if;
  -- A response to a durable pre-expiry claim may arrive after quote expiry.
  -- Persist binding for trusted webhook reconciliation without refreshing quote.
  execute replace(d,anchor,'');
 end if;
 -- Add renewal guard regardless of activation rollout: manual renewal cannot
 -- extend an effective paid cycle early. No recurring collection engine exists.
 f:=to_regprocedure('public.billing_create_or_reuse_subscription_order(uuid,text,text,uuid,uuid,text,text,text,bigint,text,integer,text,integer,text,text,uuid)');
 if f is null then raise exception 'CHECKOUT_NATIVE_ORDER_REQUIRED';end if;
 d:=replace(pg_get_functiondef(f),chr(13),'');anchor:='  -- D3: Atomically verify plan and version publication status and lock catalog row';
 guard:=$guard$if p_purchase_purpose='renew' and (exists(select 1 from public.billing_subscriptions where company_id=p_company_id and environment=p_provider_environment and paid_through>clock_timestamp()) or p_provider_environment='live' and (private.master_activation_waiting(p_company_id) or private.master_activation_company_end(p_company_id)>clock_timestamp())) then return jsonb_build_object('ok',false,'code','SUBSCRIPTION_CYCLE_NOT_ENDED','block_new_collection',true);end if;$guard$;
 if (length(d)-length(replace(d,anchor,'')))/length(anchor)<>1 then raise exception 'CHECKOUT_RENEW_BODY_REQUIRES_REVIEW';end if;
 execute replace(d,anchor,guard||E'\n'||anchor);
 -- Native FIX-05 is still the only financial retry allocator. A deadline fence
 -- on its private implementation also secures all existing public callers.
 f:=to_regprocedure('private.billing_open_payment_attempt_after_confirmed_failed(uuid,uuid,uuid,text)');
 if f is null then raise exception 'CHECKOUT_NATIVE_RETRY_REQUIRED';end if;
 d:=replace(pg_get_functiondef(f),chr(13),'');anchor:='  select *'||E'\n'||'  into v_order';
 guard:=$guard$
 perform 1 from public.companies where id=p_company_id for update;
 if exists(select 1 from private.master_checkout_quotes where order_id=p_order_id and company_id=p_company_id and quote_expires_at<=clock_timestamp()) then raise exception 'CHECKOUT_QUOTE_EXPIRED' using errcode='22023';end if;
 $guard$;
 if (length(d)-length(replace(d,anchor,'')))/length(anchor)<>1 then raise exception 'CHECKOUT_RETRY_BODY_REQUIRES_REVIEW';end if;
 execute replace(d,anchor,guard||E'\n'||anchor);
end;$$;
revoke all on function private.master_checkout_immutable(),private.master_checkout_pin_quote(),private.master_checkout_order_clock(),public.master_read_checkout_terms(uuid,uuid,uuid,uuid),public.master_accept_checkout_consent(uuid,uuid,uuid,uuid,text,boolean) from public,anon,authenticated,service_role;
grant execute on function public.master_read_checkout_terms(uuid,uuid,uuid,uuid),public.master_accept_checkout_consent(uuid,uuid,uuid,uuid,text,boolean) to service_role;
notify pgrst,'reload schema';
commit;
